insert into public.sinteria_content(id,payload) values(true,'{"brand": {"headline": "Que tu fiesta", "highlight": "se vuelva inolvidable.", "description": "Horas locas, personajes y shows que encienden la celebración. Tú pon la fecha. Nosotros, la diversión.", "whatsapp": "51952391268", "email": "sinteria.produciones@gmail.com", "ruc": "10742038551", "group": "Sinteria Group", "coverage": "Lima · otros destinos previa coordinación", "hero": "https://sinteriaproducciones.github.io/sinteria-producciones./media/117021.jpg", "heroIsConcept": false}, "socials": {"facebook": "https://www.facebook.com/share/1C4UkSgPaq/", "tiktok": "https://www.tiktok.com/@sinteria.producci", "instagram": ""}, "packages": [{"id": "hora-loca-1", "name": "La chispa", "subtitle": "1 personaje", "category": "Hora loca", "description": "El toque de energía que transforma tu celebración y pone a todos en modo fiesta.", "price": 180, "includes": ["1 personaje a elección disponible", "Show para tu celebración", "Coordinación personalizada"], "featured": false, "published": true, "format": "plan", "image": "https://sinteriaproducciones.github.io/sinteria-producciones./media/117017.jpg"}, {"id": "hora-loca-2", "name": "Fiesta en dúo", "subtitle": "2 personajes", "category": "Hora loca", "description": "Dos personajes, más interacción y un momento que tus invitados van a recordar.", "price": 280, "includes": ["2 personajes a elección disponibles", "Show para tu celebración", "Coordinación personalizada"], "featured": true, "published": true, "format": "plan", "image": "https://sinteriaproducciones.github.io/sinteria-producciones./media/117021.jpg"}, {"id": "hora-loca-3", "name": "Modo celebración", "subtitle": "3 personajes", "category": "Hora loca", "description": "Una combinación de personajes para llevar la energía de tu evento al siguiente nivel.", "price": 380, "includes": ["3 personajes a elección disponibles", "Show para tu celebración", "Coordinación personalizada"], "featured": false, "published": true, "format": "plan", "image": "https://sinteriaproducciones.github.io/sinteria-producciones./media/117024.jpg"}], "gallery": [{"id": "sinteria-19dfabe8114a65fef22533ed", "title": "Cuy listo para la fiesta", "category": "Personajes", "kind": "image", "url": "https://sinteriaproducciones.github.io/sinteria-producciones./media/117017.jpg", "published": true, "isConcept": false}, {"id": "sinteria-3c853d6b1028a517efff5f71", "title": "Personaje verde en acción", "category": "Personajes", "kind": "video", "url": "https://sinteriaproducciones.github.io/sinteria-producciones./media/119874.mp4", "published": true, "isConcept": false, "poster": "https://sinteriaproducciones.github.io/sinteria-producciones./media/119874.jpg"}, {"id": "sinteria-7737c699b090103ed13702d5", "title": "Hora loca con dos personajes", "category": "Horas locas", "kind": "image", "url": "https://sinteriaproducciones.github.io/sinteria-producciones./media/117018.jpg", "published": true, "isConcept": false}, {"id": "sinteria-397beee53341dfca41554ce7", "title": "Baile con personajes de pelo rubio", "category": "Shows", "kind": "video", "url": "https://sinteriaproducciones.github.io/sinteria-producciones./media/119875.mp4", "published": true, "isConcept": false, "poster": "https://sinteriaproducciones.github.io/sinteria-producciones./media/119875.jpg"}, {"id": "sinteria-09d7eea343527e7b0eb84a81", "title": "Tiburón azul en acción", "category": "Personajes", "kind": "image", "url": "https://sinteriaproducciones.github.io/sinteria-producciones./media/117019.jpg", "published": true, "isConcept": false}, {"id": "sinteria-5fa1657c7c98eeb30ee5b296", "title": "Hora loca con tiburón azul", "category": "Horas locas", "kind": "video", "url": "https://sinteriaproducciones.github.io/sinteria-producciones./media/119876.mp4", "published": true, "isConcept": false, "poster": "https://sinteriaproducciones.github.io/sinteria-producciones./media/119876.jpg"}, {"id": "sinteria-2e03c519dd1441c8f01c9799", "title": "Alegr